SELECT dept_name_group, location, location_list, stddev_budget FROM (SELECT CASE WHEN dept_name IN ('Legal', 'Finance') THEN 'core' ELSE 'other' END dept_name_group, location, SORT_ARRAY(COLLECT_SET(location)) location_list, ROUND(STDDEV(budget), 2) stddev_budget FROM departments WHERE budget <= 1179000 GROUP BY CASE WHEN dept_name IN ('Legal', 'Finance') THEN 'core' ELSE 'other' END, location) agg WHERE stddev_budget > 30
